function cableParts(f){return RouteGeometry.parts(f.coordinates,f.cable?.status||'Neprogramate',f.cable?.sections||[]);}
function featureLayers(f){return f.type==='LineString'?[...new Set(cableParts(f).map(p=>'Cabluri/'+p.status))]:[f.category];}
function cableRecord(f){const group=L.featureGroup();for(const part of cableParts(f)){const line=L.polyline(part.coordinates,{color:cableColors[part.status],weight:f.style.width,opacity:f.style.opacity});line._ttiLayer='Cabluri/'+part.status;line.bindTooltip(el('span',f.name+' · '+part.status+(part.section?' · '+weekLabel(part.section.week):'')));line.on('click',()=>{if(!TTI.cablePicking)show(f);});group.addLayer(line);}return group;}
TTI.cancelCableSelection=function(){if(this.cancelSelection){this.cancelSelection();this.cancelSelection=null;}this.cablePicking=false;};
TTI.addCableEditor=function(f,content){
 content.querySelector('.detail-category').textContent='Cabluri · '+featureLayers(f).map(k=>k.slice(8)).join(' / ');
 const block=el('section',undefined,'point-editor');block.append(el('h3','Patrulare traseu'));
 block.append(el('p','Săptămână programată (cablu integral): '+weekLabel(f.cable.scheduled_week)),el('p','Săptămână patrulată (cablu integral): '+weekLabel(f.cable.patrolled_week)));
 const history=el('div',undefined,'section-history');for(const section of f.cable.sections||[]){const row=el('article',undefined,'observation');const start=RouteGeometry.at(f.coordinates,section.start_pos),end=RouteGeometry.at(f.coordinates,section.end_pos);row.append(el('strong',section.status+' · '+weekLabel(section.week)),el('p','START: '+start.map(n=>n.toFixed(6)).join(', ')+'\nFINISH: '+end.map(n=>n.toFixed(6)).join(', ')));history.append(row);}if(history.children.length){block.append(el('h3','Porțiuni înregistrate'),history);}
 if(this.offline||!this.api){block.append(el('p','Salvarea comună este momentan indisponibilă.'));content.append(block);return;}
 const layerLabel=el('label','Strat pentru porțiunea selectată'),select=el('select');for(const status of cableStatuses){const option=el('option',status);option.value=status;option.selected=status===f.cable.status;select.append(option);}layerLabel.append(select);
 const weekLabelNode=el('label','Săptămâna'),week=el('input');week.type='week';weekLabelNode.append(week);
 const wholeLabel=el('label'),whole=el('input');whole.type='checkbox';wholeLabel.append(whole,el('span',' Tot cablul'));
 const pick=el('button','Selectează START și FINISH pe hartă'),range=el('p','Nicio porțiune selectată.','section-range'),message=el('p',undefined,'save-status');message.setAttribute('role','status');
 let positions=[],pins=[],preview=null,handler=null,pendingId=null;
 const cleanup=()=>{if(handler)map.off('click',handler);handler=null;this.cablePicking=false;map.getContainer().classList.remove('placing-point');pins.forEach(pin=>map.removeLayer(pin));pins=[];if(preview)map.removeLayer(preview);preview=null;};this.cancelSelection=cleanup;
 const draw=()=>{pins.forEach(pin=>map.removeLayer(pin));pins=positions.map((p,i)=>L.marker(RouteGeometry.at(f.coordinates,p),{icon:L.divIcon({html:el('span',i===0?'START':'FINISH','endpoint-pin'),className:'endpoint-icon',iconSize:[65,24],iconAnchor:[32,12]}),interactive:false}).addTo(map));if(preview)map.removeLayer(preview);if(positions.length===2)preview=L.polyline(RouteGeometry.slice(f.coordinates,Math.min(...positions),Math.max(...positions)),{color:cableColors[select.value],weight:9,opacity:.6,interactive:false}).addTo(map);};
 pick.onclick=()=>{cleanup();whole.checked=false;positions=[];pendingId=null;this.cablePicking=true;map.getContainer().classList.add('placing-point');range.textContent='Click pe traseu pentru START.';handler=e=>{const hit=RouteGeometry.nearest(f.coordinates,[e.latlng.lat,e.latlng.lng]);const clickPoint=map.latLngToContainerPoint(e.latlng),snapPoint=map.latLngToContainerPoint(hit.coordinate);if(clickPoint.distanceTo(snapPoint)>35){range.textContent='Alege o poziție pe cablul selectat (mărește harta dacă este nevoie).';return;}positions.push(hit.position);draw();if(positions.length===1)range.textContent='START ales. Click pe traseu pentru FINISH.';else{map.off('click',handler);handler=null;this.cablePicking=false;map.getContainer().classList.remove('placing-point');range.textContent='START: '+RouteGeometry.at(f.coordinates,positions[0]).map(n=>n.toFixed(6)).join(', ')+'\nFINISH: '+RouteGeometry.at(f.coordinates,positions[1]).map(n=>n.toFixed(6)).join(', ');}};map.on('click',handler);};
 whole.onchange=()=>{cleanup();positions=[];pendingId=null;range.textContent=whole.checked?'Va fi marcat întregul cablu.':'Nicio porțiune selectată.';pick.disabled=whole.checked;};
 const update=()=>{cleanup();positions=[];pendingId=null;week.required=select.value!=='Neprogramate';week.value=(select.value==='Patrulate'?f.cable.patrolled_week:f.cable.scheduled_week)||'';wholeLabel.hidden=pick.hidden=range.hidden=select.value==='Neprogramate';weekLabelNode.hidden=select.value==='Neprogramate';range.textContent='Nicio porțiune selectată.';};select.onchange=update;update();
 const save=el('button','Salvează porțiunea','save-point');save.onclick=async()=>{if(this.busy||!week.reportValidity())return;if(select.value!=='Neprogramate'&&!whole.checked&&positions.length!==2){message.textContent='Selectează START și FINISH pe hartă sau bifează Tot cablul.';return;}
 this.busy=true;save.disabled=true;try{if(select.value==='Neprogramate'){await this.request('/cables/'+f.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'Neprogramate',scheduled_week:f.cable.scheduled_week,patrolled_week:f.cable.patrolled_week,version:f.cable.version})});}else{const bounds=whole.checked?[0,f.coordinates.length-1]:positions;pendingId=pendingId||crypto.randomUUID();await this.request('/cables/'+f.id+'/sections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:pendingId,status:select.value,week:week.value,start_pos:bounds[0],end_pos:bounds[1],version:f.cable.version})});}
 cleanup();await this.refresh();enabled.set('Cabluri/'+select.value,true);render();show(f);}catch(error){message.textContent=error.message;const reload=el('button','Reîncarcă traseul');reload.onclick=async()=>{cleanup();await this.refresh();show(f);};block.append(reload);}finally{this.busy=false;save.disabled=false;}};
 block.append(layerLabel,weekLabelNode,wholeLabel,pick,range,save,message);content.append(block);
};
